import {test} from 'node:test';import assert from 'node:assert/strict';import {createSimulation,step,releaseBlock} from './simulation.js';
test('empty truck is not completed until its cargo is stored; blocked ware waits',()=>{const s=createSimulation();for(let i=0;i<2000;i++)step(s,.1);assert.equal(s.wares[0].departed,true);assert.equal(s.wares[1].departed,false);assert.equal(s.tasks.filter(t=>t.status==='blocked').length,1);releaseBlock(s);for(let i=0;i<100;i++)step(s,.1);assert(s.wares.every(w=>w.departed));assert(s.tasks.every(t=>t.status==='stored'));assert(s.workers.every(w=>w.task===null))});
test('deterministic reset and unique assignments',()=>{const s=createSimulation();for(let i=0;i<200;i++){step(s,.1);const tasks=s.workers.map(w=>w.task).filter(Boolean);assert.equal(new Set(tasks).size,tasks.length)}assert.equal(createSimulation().time,0);assert.equal(createSimulation().tasks.length,16)});
